ar(--gp-superficie-2);\n    --exv-tinta: var(--gp-texto);\n    --exv-tinta-suave: var(--gp-texto-2);\n    --exv-tinta-tenue: var(--gp-texto-3);\n    --exv-bronce: var(--gp-ambar);\n    --exv-bronce-oscuro: var(--gp-azul-texto);\n    --exv-bronce-tinte: var(--gp-azul-suave);\n    --exv-sobre-acento: var(--gp-sobre-acento);\n    --exv-verde: var(--gp-verde-texto);\n    --exv-verde-tinte: var(--gp-verde-suave);\n    --exv-linea: var(--gp-linea-fuerte);\n    --exv-linea-suave: var(--gp-linea);\n    --exv-alerta: var(--gp-coral);\n    --exv-alerta-tinte: var(--gp-coral-suave);\n    --exv-a12: var(--gp-azul-texto);\n    --exv-a12-tinte: var(--gp-azul-suave);\n    --exv-radio: var(--gp-radio);\n    color: var(--exv-tinta);\n}\n\n.exv-contenido { max-width: 96rem; margin: 0 auto; }\n\n.exv-solo-impresion { display: none; }\n\n/* Encabezado */\n.exv-titulo {\n    display: flex;\n    align-items: center;\n    gap: 1rem;\n    flex-wrap: wrap;\n    margin-bottom: 1.25rem;\n}\n.exv-titulo-texto { flex: 1; min-width: 240px; }\n.exv-titulo-texto h2 { font-size: 1.5rem; line-height: 1.2; font-weight: 800; margin: .2rem 0 0; color: var(--exv-tinta); }\n.exv-subtitulo { display: flex; flex-wrap: wrap; gap: .25rem .75rem; align-items: baseline; margin: .3rem 0 0; font-size: .9rem; color: var(--exv-tinta-suave); }\n.exv-subtitulo b { font-weight: 700; color: var(--exv-tinta); }\n.exv-vacio-plantillas { font-size: .85rem !important; color: var(--exv-tinta-suave); }\n.exv-resumen-impresion h2 small { margin-left: .5rem; font-size: .8rem; font-weight: 400; }\n.exv-eyebrow { font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; color: var(--exv-bronce-oscuro); }\n.exv-titulo-acciones { display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }\n.exv-titulo-acciones select {\n    font-size: .85rem;\n    padding: .5rem .6rem;\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n    background: var(--exv-control);\n    color: var(--exv-tinta);\n    max-width: 100%;\n}\n\n/* Botones */\n.exv-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: .4rem;\n    font-size: .82rem;\n    font-weight: 600;\n    border: 1px solid var(--exv-linea);\n    background: var(--exv-control);\n    color: var(--exv-tinta-suave);\n    padding: .5rem .85rem;\n    border-radius: var(--exv-radio);\n    cursor: pointer;\n    transition: border-color .12s, color .12s, background .12s;\n}\n.exv-btn:hover:not(:disabled) { border-color: var(--exv-bronce); color: var(--exv-bronce-oscuro); }\n.exv-btn:disabled { opacity: .55; cursor: not-allowed; }\n.exv-btn-primario { background: var(--exv-bronce); border-color: var(--exv-bronce); color: var(--exv-sobre-acento); }\n.exv-btn-primario:hover:not(:disabled) { background: #F5B62E; border-color: #F5B62E; color: var(--exv-sobre-acento); }\n.exv-btn-peligro:hover:not(:disabled) { border-color: var(--exv-alerta); color: var(--exv-alerta); }\n\n/* Distribución */\n.exv-shell {\n    display: grid;\n    grid-template-columns: 330px minmax(0, 1fr);\n    gap: 1.5rem;\n    align-items: start;\n}\n.exv-shell.plegada { grid-template-columns: minmax(0, 1fr); }\n.exv-tablero { min-width: 0; }\n\n/* Configuración inicial: se confirma una vez, antes de poder chequear */\n.exv-confirmar {\n    padding: 1.25rem 1.4rem;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea);\n    border-top: 3px solid var(--exv-bronce);\n    border-radius: var(--exv-radio);\n}\n.exv-confirmar h3 { margin: 0 0 .5rem; font-size: 1.05rem; font-weight: 700; color: var(--exv-tinta); }\n.exv-confirmar p { margin: 0 0 1rem; font-size: .88rem; line-height: 1.5; color: var(--exv-tinta-suave); }\n.exv-confirmar-pie {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: .75rem;\n    padding-top: .9rem;\n    font-size: .88rem;\n    font-weight: 600;\n    border-top: 1px solid var(--exv-linea-suave);\n}\n\n/* Configuración plegada: se ve de un vistazo sin ocupar la pantalla */\n.exv-config-resumen {\n    display: flex;\n    flex-wrap: wrap;\n    gap: .35rem 1.25rem;\n    padding: .55rem .9rem;\n    margin-bottom: 1rem;\n    font-size: .8rem;\n    color: var(--exv-tinta-suave);\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea-suave);\n    border-radius: var(--exv-radio);\n}\n.exv-config-resumen b { margin-right: .25rem; font-weight: 700; color: var(--exv-tinta); }\n\n/* Plantilla con versión nueva: en la franja de configuración o al configurar */\n.exv-version-nueva { display: inline-flex; flex-wrap: wrap; align-items: center; gap: .25rem .5rem; color: var(--exv-a12); }\n.exv-version-nueva b { color: var(--exv-tinta); }\n.exv-version-nueva .exv-btn { padding: .2rem .6rem; font-size: .76rem; }\n.exv-versiones-nuevas { display: flex; flex-direction: column; align-items: flex-start; gap: .4rem; }\n\n/* Vista previa de una versión nueva, dentro de Swal: fuera de .exv-pagina, con los tokens --gp-* */\n.exv-vista-version { max-height: 60vh; overflow-y: auto; text-align: left; font-size: .88rem; line-height: 1.45; }\n.exv-vista-version p { margin: 0 0 .6rem; }\n.exv-vista-version b { color: var(--gp-texto); }\n.exv-vista-descripcion { white-space: pre-line; color: var(--gp-texto-3); }\n.exv-vista-igual { font-weight: 600; color: var(--gp-texto); }\n.exv-vista-version section { margin: .9rem 0; }\n.exv-vista-version h3 { margin: 0 0 .35rem; font-size: .92rem; font-weight: 700; color: var(--gp-texto); }\n.exv-vista-version ul { margin: 0; padding-left: 1.2rem; }\n.exv-vista-version li { margin-bottom: .3rem; }\n.exv-vista-ahora { display: block; color: var(--gp-azul-texto); }\n.exv-vista-etiqueta {\n    display: inline-block;\n    padding: 0 .4rem;\n    font-size: .74rem;\n    color: var(--gp-texto-2);\n    background: var(--gp-superficie-3);\n    border-radius: var(--gp-radio);\n}\n.exv-vista-mas { list-style: none; margin-left: -1.2rem; color: var(--gp-texto-3); }\n\n/* Panel de configuración */\n.exv-config {\n    position: sticky;\n    top: 1rem;\n    max-height: calc(100dvh - 2rem);\n    overflow-y: auto;\n    background: var(--exv-tarjeta);\n    border: 1px solid var(--exv-linea);\n    border-radius: var(--exv-radio);\n}\n.exv-config-head {\n    position: sticky;\n    top: 0;\n    z-index: 2;\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    padding: .85rem 1.1rem;\n    background: var(--exv-tarjeta);\n    border-bottom: 1px solid var(--exv-linea-suave);\n}\n.exv-config-head h2 { font-size: .82rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; margin: 0; color: var(--exv-tinta); }\n.exv-config-head span { font-size: .75rem; color: var(--exv-tinta-tenue); }\n.exv-config fieldset { border: 0; margin: 0; padding: 1rem 1.1rem; border-bottom: 1px solid var(--exv-linea-suave); min-width: 0; }\n.exv-config fieldset:last-of-type { border-bottom: 0; }\n.exv-config legend {\n    display: block;\n    float: left;\n    width: 100%;\n    padding: 0;\n    margin-bottom: .6rem;\n    font-size: .7rem;\n    font-weight: 700;\n    letter-spacing: .1em;\n    text-transform: uppercase;\n    color: var(--exv-bronce-oscuro);\n}\n.exv-config legend small { font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--exv-tinta-tenue); }\n.exv-config legend + * { clear: both; }\n.exv-tipos { background: var(--exv-bronce-tinte); }\n.exv-tipo-grupo { margin-bottom: .5rem; }\n.exv-tipo-grupo:last-child { margin-bottom: 0; }\n.exv-tipo-titulo {\n    margin: .5rem 0 .2rem;\n    padding-top: .4rem;\n    border-top: 1px solid var(--exv-linea);\n    font-size: .68rem;\n    font-weight: 700;\n    letter-spacing: .06em;\n    text-transform: uppercase;\n    color: var(--exv-bronce-oscuro);\n}\n.exv-tipo-grupo:first-of-type .exv-tipo-titulo { margin-top: 0; padding-top: 0; border-top: 0; }\n\n.exv-opt {\n    display: flex;\n    align-items: flex-start;\n    gap: .6rem;\n    padding: .32rem 0;\n    font-s